(function () {
  "use strict";

  function find(selector, parent) {
    return selector ? (parent || document).querySelector(selector) : null;
  }

  function dispatch(name, elt, detail) {
    var event = new CustomEvent(name, {
      bubbles: true,
      cancelable: name === "htmx:beforeRequest",
      detail: Object.assign({ elt: elt }, detail || {})
    });
    elt.dispatchEvent(event);
    return event;
  }

  function triggerDelay(elt) {
    var trigger = elt.getAttribute("hx-trigger") || "";
    var match = trigger.match(/delay:(\d+)ms/i);
    return match ? parseInt(match[1], 10) : 160;
  }

  function swap(target, html) {
    target.innerHTML = html;
    dispatch("htmx:afterSwap", target, { target: target });
  }

  function request(elt) {
    var method = elt.getAttribute("hx-post") ? "POST" : "GET";
    var url = elt.getAttribute("hx-post") || elt.getAttribute("hx-get");
    var target = find(elt.getAttribute("hx-target") || "");
    if (!url || !target) return;

    var form = elt.tagName === "FORM" ? elt : (elt.form || elt.closest("form"));
    var data = form ? new FormData(form) : new FormData();
    if (elt.name && elt.value) data.set(elt.name, elt.value);

    var before = dispatch("htmx:beforeRequest", elt, {
      target: target,
      requestConfig: { method: method, url: url }
    });
    if (before.defaultPrevented) return;

    var fetchUrl = url;
    var options = {
      method: method,
      credentials: "same-origin",
      headers: { "HX-Request": "true" }
    };

    if (method === "GET") {
      var params = new URLSearchParams(data);
      fetchUrl += (url.indexOf("?") > -1 ? "&" : "?") + params.toString();
    } else {
      options.body = data;
    }

    fetch(fetchUrl, options)
      .then(function (response) {
        if (!response.ok) {
          dispatch("htmx:responseError", elt, { target: target, response: response });
          throw new Error("HTMX response error");
        }
        return response.text().then(function (html) {
          swap(target, html);
          dispatch("htmx:afterRequest", elt, { target: target, response: response, successful: true });
        });
      })
      .catch(function (error) {
        if (error && error.message === "HTMX response error") return;
        dispatch("htmx:sendError", elt, { target: target, error: error });
      });
  }

  function bind(elt) {
    if (elt.dataset.hxBound === "true") return;
    elt.dataset.hxBound = "true";

    var wait = triggerDelay(elt);
    var timer = null;
    ["input", "change", "keyup"].forEach(function (eventName) {
      elt.addEventListener(eventName, function () {
        clearTimeout(timer);
        timer = setTimeout(function () { request(elt); }, wait);
      });
    });

    if (elt.tagName === "FORM") {
      elt.addEventListener("submit", function (event) {
        event.preventDefault();
        request(elt);
      });
    }
  }

  function boot(root) {
    (root || document).querySelectorAll("[hx-get], [hx-post]").forEach(bind);
  }

  document.body && document.body.addEventListener("htmx:afterSwap", function (event) {
    boot(event.detail && event.detail.target ? event.detail.target : document);
  });

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { boot(document); });
  } else {
    boot(document);
  }
})();
